import{i as e,o as t,r as n,t as r}from"./app-BHhOoUAS.js";import"./helloworld-THjBwPkR.js";var i=JSON.parse(`{"path":"/docs/%E5%BC%80%E5%A7%8B/%E7%AB%A0%E8%8A%82%E6%A6%82%E5%BF%B5.html","title":"章节概念","lang":"zh-CN","frontmatter":{"description":"说明 Dvnge 视觉小说引擎的章节系统，了解如何创建章节文件、配置章节列表、编写游戏逻辑。"},"filePathRelative":"docs/开始/章节概念.md","git":{"createdTime":1781703562000,"updatedTime":1791985230000,"contributors":[{"name":"TTQWNTian","username":"TTQWNTian","email":"ttqwntian@qq.com","commits":4,"url":"https://github.com/TTQWNTian"}]}}`),a={name:`章节概念.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="章节概念" tabindex="-1"><a class="header-anchor" href="#章节概念"><span>章节概念</span></a></h1><p>章节是使用 Dvnge 制作游戏的基本，它们是在 <code>chapter/</code> 文件夹中的文件。引擎支持两种章节文件格式：</p><ul><li><strong><code>.dvns</code> 文件</strong>：Dvnge 独创的剧本语法，写起来简洁，推荐使用。</li><li><strong><code>.js</code> 文件</strong>：用 JavaScript 对象数组描述节点，类 Json 语法，适合比较复杂脚本场景。</li></ul><p>两种格式可以混用，引擎按 <code>章节文件列表</code> 里配置的路径后缀自动识别。</p><h2 id="使用-dvns-文件" tabindex="-1"><a class="header-anchor" href="#使用-dvns-文件"><span>使用 dvns 文件</span></a></h2><p>在 <code>chapter/</code> 文件夹中创建一个 <code>序章.dvns</code> 文件，然后里面写上这样的代码：</p><div class="language-dvns line-numbers-mode" data-highlighter="prismjs" data-ext="dvns"><pre><code class="language-dvns"><span class="line">&quot;Tian&quot;: 你好，世界。$</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>之后保存文件，这样就写好了一个基础的对话（现在看不懂为什么这么写不要紧，之后都会详细讲解）。</p><h2 id="使用-js-文件" tabindex="-1"><a class="header-anchor" href="#使用-js-文件"><span>使用 js 文件</span></a></h2><p>在 <code>chapter/</code> 文件夹中创建一个 <code>序章.js</code> 文件，然后里面写上这样的代码：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">var</span> 序章 <span class="token operator">=</span> <span class="token punctuation">[</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        <span class="token literal-property property">角色</span><span class="token operator">:</span> <span class="token string">&quot;Tian&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token literal-property property">内容</span><span class="token operator">:</span> <span class="token string">&quot;你好，世界。&quot;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>变量名要和章节名一致，引擎靠它拿到节点列表。</li><li>每个元素是一个节点，节点里可以写 <code>角色</code>、<code>内容</code>、<code>立绘</code>、<code>背景</code> 等属性。</li></ul><h2 id="配置章节列表" tabindex="-1"><a class="header-anchor" href="#配置章节列表"><span>配置章节列表</span></a></h2><p>只创建文件是不起作用的，我们还需要在 <code>js/游戏配置.js</code> 中加上所添加的章节路径。</p><p>在 <code>js/游戏配置.js</code> 文件中找到 <code>章节文件列表</code>，然后在末尾添加对应的行。</p><p><code>.dvns</code> ：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token punctuation">{</span> <span class="token literal-property property">名称</span><span class="token operator">:</span> <span class="token string">&quot;序章&quot;</span><span class="token punctuation">,</span> <span class="token literal-property property">路径</span><span class="token operator">:</span> <span class="token string">&quot;chapter/序章.dvns&quot;</span> <span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><code>.js</code> ：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token punctuation">{</span> <span class="token literal-property property">名称</span><span class="token operator">:</span> <span class="token string">&quot;序章&quot;</span><span class="token punctuation">,</span> <span class="token literal-property property">路径</span><span class="token operator">:</span> <span class="token string">&quot;chapter/序章.js&quot;</span> <span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>加上后完整的 <code>章节文件列表</code> 代码是这样的：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> 章节文件列表 <span class="token operator">=</span> <span class="token punctuation">[</span></span>
<span class="line">    <span class="token punctuation">{</span> <span class="token literal-property property">名称</span><span class="token operator">:</span> <span class="token string">&quot;序章&quot;</span><span class="token punctuation">,</span> <span class="token literal-property property">路径</span><span class="token operator">:</span> <span class="token string">&quot;chapter/序章.dvns&quot;</span> <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这样添加章节的配置就完成了！运行 <code>game.html</code> 就可以看到我们写的对话了。</p><p><img src="/docsImg/helloworld.webp" alt="helloworld.webp"></p>`,23)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};